              <span className={`w-2 h-2 rounded-full animate-pulse ${repoStatus === 'connected' ? 'bg-emerald-500' : 'bg-rose-500'}`}></span>
              <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">{MAIN_REPO}</p>
