            <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${repoStatus === 'connected' ? 'bg-emerald-900/30 text-emerald-400' : 'bg-rose-900/30 text-rose-400'}`}>
              {repoStatus.toUpperCase()}
            </span>
          </div>
