            <div className="bg-emerald-950/20 border-2 border-emerald-500/30 p-12 rounded-[3.5rem] shadow-2xl relative overflow-hidden">
               <div className="relative z-10 space-y-10">
                 <div>
                   <h3 className="text-3xl font-black text-white tracking-tight">Public Link Generation</h3>
                   <p className="text-xs font-bold text-emerald-400 uppercase tracking-widest">Sharing without showing source code</p>
